/**
 * Breadcrumb generator producing visible nav markup plus schema.org JSON-LD.
 */

/**
 * Escape a value for use inside a double-quoted HTML attribute.
 * Escapes &, ", <, > so URLs with quotes/ampersands are safe.
 * (& is escaped first.)
 */
function escapeAttr(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * Render breadcrumb markup for a trail of items.
 *
 * @param {Array<{name: string, url: string}>} items
 *   Ordered trail; the last item is the current page (rendered as a span
 *   with aria-current="page", no href).
 * @returns {{html: string, jsonLd: string}} The nav markup and the
 *   contents of the application/ld+json script tag.
 */
export function render(items) {
  if (!Array.isArray(items)) {
    throw new TypeError('render(items) expects an array of {name, url}');
  }
  if (items.length === 0) {
    throw new Error('render(items) requires at least one item');
  }

  const links = items.map(({ name, url }) => ({ name: String(name), url: String(url) }));

  // Visible markup: <nav aria-label="Breadcrumb"><ol>…</ol></nav>.
  // Every item except the last is an anchor; the last is a span with
  // aria-current="page" and no href.
  const listItems = links
    .map((item, i) => {
      if (i === links.length - 1) {
        return `      <li><span aria-current="page">${escapeAttr(item.name)}</span></li>`;
      }
      return `      <li><a href="${escapeAttr(item.url)}">${escapeAttr(item.name)}</a></li>`;
    })
    .join('\n');

  const html = [
    '<nav aria-label="Breadcrumb">',
    '  <ol>',
    listItems,
    '  </ol>',
    '</nav>',
  ].join('\n');

  // Structured data: BreadcrumbList with 1-based positions.
  const data = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: links.map((item, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: item.name,
      item: item.url,
    })),
  };

  return {
    html,
    jsonLd: JSON.stringify(data),
  };
}

