import { describe, it, expect } from 'vitest';
import { parse } from 'node-html-parser';
import { render } from '../src/breadcrumbs.js';

const TRAIL = [
  { name: 'Home', url: 'https://example.com/' },
  { name: 'Catalog', url: 'https://example.com/catalog' },
  { name: 'Widgets', url: 'https://example.com/catalog/widgets' },
  { name: 'Super Widget', url: 'https://example.com/catalog/widgets/super-widget' },
];

function extractJsonLd(html) {
  const root = parse(html);
  const script = root.querySelector('script[type="application/ld+json"]');
  expect(script, 'expected an application/ld+json script element').toBeTruthy();
  return JSON.parse(script.text);
}

describe('render(items) — visible markup', () => {
  it('wraps the list in a nav with aria-label "Breadcrumb"', () => {
    const { html } = render(TRAIL);
    const root = parse(html);
    const nav = root.querySelector('nav[aria-label="Breadcrumb"]');
    expect(nav).toBeTruthy();
  });

  it('renders an ordered list with one li per item, in order', () => {
    const { html } = render(TRAIL);
    const root = parse(html);
    const items = root.querySelectorAll('nav ol > li');
    expect(items.length).toBe(TRAIL.length);
    // Order preserved
    const anchors = items.slice(0, -1).map((li) => li.querySelector('a'));
    anchors.forEach((a, i) => {
      expect(a.getAttribute('href')).toBe(TRAIL[i].url);
      expect(a.text.trim()).toBe(TRAIL[i].name);
    });
  });

  it('renders the last item as a span with aria-current="page" and no href', () => {
    const { html } = render(TRAIL);
    const root = parse(html);
    const lis = root.querySelectorAll('nav ol > li');
    const lastLi = lis[lis.length - 1];

    // No anchor inside the last item
    expect(lastLi.querySelector('a')).toBeNull();

    const span = lastLi.querySelector('span[aria-current="page"]');
    expect(span).toBeTruthy();
    expect(span.text.trim()).toBe(TRAIL[TRAIL.length - 1].name);
    // No href attribute anywhere in the last item
    const withHref = lastLi.querySelectorAll('[href]');
    expect(withHref.length).toBe(0);
  });

  it('only places aria-current on the final span', () => {
    const { html } = render(TRAIL);
    const root = parse(html);
    const current = root.querySelectorAll('[aria-current="page"]');
    expect(current.length).toBe(1);
  });
});

describe('render(items) — JSON-LD structured data', () => {
  it('emits a BreadcrumbList whose JSON parses cleanly', () => {
    const data = extractJsonLd(render(TRAIL).html);
    expect(data['@context']).toBe('https://schema.org');
    expect(data['@type']).toBe('BreadcrumbList');
    expect(Array.isArray(data.itemListElement)).toBe(true);
  });

  it('positions are sequential starting at 1', () => {
    const data = extractJsonLd(render(TRAIL).html);
    const positions = data.itemListElement.map((el) => el.position);
    expect(positions).toEqual([1, 2, 3, 4]);
    for (const el of data.itemListElement) {
      expect(el['@type']).toBe('ListItem');
    }
  });

  it('names match the input trail in order', () => {
    const data = extractJsonLd(render(TRAIL).html);
    expect(data.itemListElement.map((el) => el.name)).toEqual(TRAIL.map((i) => i.name));
  });
});

describe('HTML/JSON-LD consistency and escaping', () => {
  it('names in HTML and JSON-LD stay consistent', () => {
    const { html } = render(TRAIL);
    const root = parse(html);
    const data = extractJsonLd(html);

    const htmlNames = root
      .querySelectorAll('nav ol > li > a, nav ol > li > span')
      .map((el) => el.text.trim());

    expect(htmlNames).toEqual(data.itemListElement.map((el) => el.name));
  });

  it('escapes double quotes and ampersands in URLs (attribute-safe)', () => {
    const tricky = [
      { name: 'Search & Results', url: 'https://example.com/search?q="quoted"&filter=a&b=1' },
      { name: 'Current', url: 'https://example.com/search/result?id=42&lang=en' },
    ];
    const { html } = render(tricky);

    // The raw HTML must not contain an unescaped quote inside attributes —
    // parsing back must yield the exact original URLs.
    const root = parse(html);
    const hrefs = root.querySelectorAll('nav ol > li a').map((a) => a.getAttribute('href'));
    expect(hrefs).toEqual([tricky[0].url]);

    const span = root.querySelector('span[aria-current="page"]');
    expect(span.text.trim()).toBe('Current');

    // No raw double quote should appear inside any attribute value boundary;
    // i.e. escaped form is used in the source markup.
    expect(html).toContain('&quot;');
    expect(html).toContain('&amp;');

    // JSON-LD round-trips the exact names/URLs too.
    const data = extractJsonLd(html);
    expect(data.itemListElement.map((el) => el.item)).toEqual(tricky.map((t) => t.url));
    expect(data.itemListElement.map((el) => el.name)).toEqual(tricky.map((t) => t.name));
  });
});

